// Node vector search must return exactly what scripts/library-vectors.py returned
// (fixture regenerated by `npx tsx scripts/parity/vector-parity.ts`).
import assert from 'node:assert/strict';
import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { searchVectors } from '../../lib/vectors/search';

const library = join(process.cwd(), '.local-library');
// 对照的是内置书库的检索结果：只有模型、没有内置书库（例如开源代码自己编译）时跳过。
if (!existsSync(join(library, 'taiwei-model/model.onnx')) || !existsSync(join(library, 'books')) || !existsSync(join(library, 'taiwei.json'))) {
  console.log('SKIP vector-search: .local-library model or bundled books not found');
  process.exit(0);
}
const fixture: { question: string; hits: unknown }[] = JSON.parse(
  readFileSync(join(__dirname, 'fixtures/vector-search-python.json'), 'utf8'));

(async () => {
  for (const { question, hits } of fixture) {
    assert.deepEqual(await searchVectors(library, question), hits, question);
  }
  assert.deepEqual(await searchVectors(library, '   '), { sample: [], books: [] });
  console.log(`PASS vector-search: ${fixture.length} questions identical to Python`);
})();
